mapper.select:
SELECT id
FROM source_effect
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND source_service=#{sourceService}
AND action=#{action}
AND fact_type=#{factType}
AND fact_parent_id=#{factParentId}
AND fact_part_id=#{factPartId}
AND fact_line_id=#{factLineId}

SELECT id
FROM source_effect
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND (active_command_id=#{commandId} OR applied_command_id=#{commandId})

SELECT id, active_command_id, applied_command_id, attempt_no, state, version
FROM source_effect
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId} FOR UPDATE

mapper.update:
UPDATE source_effect
SET active_command_id=#{commandId}, attempt_no=GREATEST(attempt_no, #{attemptNo}), state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND applied_command_id IS NULL
AND (active_command_id IS NULL OR active_command_id=#{commandId})

UPDATE source_effect
SET attempt_no=#{attemptNo}, active_command_id=#{commandId}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND version=#{expectedVersion}
AND applied_command_id IS NULL
AND state=#{fromState}

UPDATE source_effect
SET active_command_id=#{commandId}, state='SAFE_CLOSED', version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND applied_command_id IS NULL
AND state NOT IN ('STARTED','UNKNOWN','APPLIED')

mapper.select:
SELECT command_id, state, payload_digest, posting_id, attempt_no, business_effect_key, action, payload_json
FROM source_command
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND business_effect_key=#{effectId}
ORDER BY attempt_no DESC
LIMIT 1

mapper.update:
UPDATE source_command
SET safe_close_id=#{closeId}, safe_close_version=safe_close_version+1, safe_close_evidence=CAST(#{evidence} AS JSON), updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND command_id=#{commandId}

mapper.select:
SELECT command_id, state, payload_digest, posting_id, business_effect_key, safe_close_id, action, payload_json
FROM source_command
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND command_id=#{commandId}

mapper.update:
UPDATE source_command
SET state=#{state}, inventory_operation_id=#{operationId}, posting_id=#{postingId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND command_id=#{commandId}

UPDATE source_execution
SET stock_sync_status=#{syncStatus}, posted_qty=#{postedQty}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND command_id=#{commandId}

UPDATE source_effect
SET applied_command_id=CASE WHEN #{state}='APPLIED' THEN #{commandId} ELSE applied_command_id END, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{effectId}
AND (applied_command_id IS NULL
AND active_command_id=#{commandId} OR applied_command_id=#{commandId})
